165	  /* Border */
166	  --color-border-subtle: oklch(18% 0.010 220);
167	  --color-border-default: oklch(22% 0.013 220);
168	  --color-border-strong: oklch(32% 0.013 220);
169	
170	  /* Semantic — dark mode subtle backgrounds flip to dark-tinted */
171	  --color-success-subtle: oklch(18% 0.040 145);
172	  --color-success-fg: oklch(72% 0.18 145);
173	  --color-warning-subtle: oklch(18% 0.040 72);
174	  --color-warning-fg: oklch(78% 0.17 72);
175	  --color-danger-subtle: oklch(18% 0.040 27);
176	  --color-danger-fg: oklch(72% 0.20 27);
177	  --color-info-subtle: oklch(16% 0.030 230);
178	  --color-info-fg: oklch(72% 0.17 230);
179	
180	  /* shadcn token aliases — dark */
181	  --color-background: var(--color-canvas);
182	  --color-foreground: var(--color-fg-primary);
183	  --color-card: var(--color-surface);
184	  --color-card-foreground: var(--color-fg-primary);
185	  --color-popover: var(--color-overlay);
186	  --color-popover-foreground: var(--color-fg-primary);
187	  --color-primary: oklch(65% 0.20 264);
188	  --color-primary-foreground: oklch(100% 0 0);
189	  --color-secondary: oklch(18% 0.013 220);
190	  --color-secondary-foreground: var(--color-fg-primary);
191	  --color-muted: oklch(16% 0.013 220);
192	  --color-muted-foreground: var(--color-fg-secondary);
193	  --color-accent: oklch(18% 0.013 220);
194	  --color-accent-foreground: var(--color-fg-primary);
195	  --color-destructive: oklch(55% 0.22 27);
196	  --color-destructive-foreground: oklch(100% 0 0);
197	  --color-border: var(--color-border-default);
198	  --color-input: var(--color-border-default);
199	  --color-ring: oklch(65% 0.20 264);
200	
201	  /* Sidebar active/hover — dark mode */
202	  --sidebar-item-active-bg: oklch(22% 0.008 250);  /* dark — slightly lighter than sidebar bg */
203	  --sidebar-item-hover-bg: oklch(18% 0.006 250);   /* dark — in between */
204	
205	  /* Shadows — dark mode: border-dominant, minimal blur */
206	  --shadow-xs: 0 0 0 1px oklch(100% 0 0 / 0.06);
207	  --shadow-sm: 0 0 0 1px oklch(100% 0 0 / 0.07), 0 2px 4px oklch(0% 0 0 / 0.3);
208	  --shadow-md: 0 0 0 1px oklch(100% 0 0 / 0.08), 0 4px 12px oklch(0% 0 0 / 0.4);
209	  --shadow-lg: 0 0 0 1px oklch(100% 0 0 / 0.09), 0 8px 24px oklch(0% 0 0 / 0.5);
210	  --shadow-xl: 0 0 0 1px oklch(100% 0 0 / 0.10), 0 16px 48px oklch(0% 0 0 / 0.6);
211	}
212	
213	@keyframes accordion-down {
214	  from { height: 0; }
215	  to { height: var(--radix-accordion-content-height); }
216	}
217	
218	@keyframes accordion-up {
219	  from { height: var(--radix-accordion-content-height); }
220	  to { height: 0; }
221	}
222	
223	@keyframes fade-in {
224	  from { opacity: 0; transform: translateY(4px); }
225	  to { opacity: 1; transform: translateY(0); }
226	}
227	
228	@keyframes scale-in {
229	  from { opacity: 0; transform: scale(0.97); }
230	  to { opacity: 1; transform: scale(1); }
231	}
232	
233	@keyframes slide-up {
234	  from { opacity: 0; transform: translateY(16px); }
235	  to { opacity: 1; transform: translateY(0); }
236	}
237	
238	@keyframes slide-in-right {
239	  from { opacity: 0; transform: translateX(12px); }
240	  to { opacity: 1; transform: translateX(0); }
241	}
242	
243	@keyframes pulse-ring {
244	  0% { box-shadow: 0 0 0 0 color-mix(in oklch, var(--color-accent-brand) 35%, transparent); }
245	  70% { box-shadow: 0 0 0 8px transparent; }
246	  100% { box-shadow: 0 0 0 0 transparent; }
247	}
248	
249	/* ── Base styles ─────────────────────────────────────────────── */
250	
251	* {
252	  border-color: var(--color-border);
253	}
254	
255	html {
256	  scroll-behavior: smooth;
257	  -webkit-font-smoothing: antialiased;
258	  -moz-osx-font-smoothing: grayscale;
259	}
260	
261	body {
262	  background-color: var(--color-background);
263	  color: var(--color-foreground);
264	  font-family: var(--font-sans);
265	  font-feature-settings: 'cv11', 'ss01';
266	}
267	
268	*:focus-visible {
269	  outline: none;
270	  box-shadow: 0 0 0 2px var(--color-background), 0 0 0 4px color-mix(in oklch, var(--color-primary) 25%, transparent);
271	}
272	
273	/* ── Utilities ───────────────────────────────────────────────── */
274	
275	.text-balance {
276	  text-wrap: balance;
277	}
278	
279	.text-2xs {
280	  font-size: 0.6875rem;
281	  line-height: 1rem;
282	}
283	
284	.scrollbar-thin {
285	  scrollbar-width: thin;
286	  scrollbar-color: var(--color-border) transparent;
287	}
288	
289	/* ── Reduced motion ──────────────────────────────────────────── */
290	
291	@media (prefers-reduced-motion: reduce) {
292	  *,
293	  *::before,
294	  *::after {
295	    animation-duration: 0.01ms !important;
296	    animation-iteration-count: 1 !important;
297	    transition-duration: 0.01ms !important;
298	  }
299	}
300	
301	/* ── Custom scrollbar (WebKit) ───────────────────────────────── */
302	
303	::-webkit-scrollbar {
304	  width: 6px;
305	  height: 6px;
306	}
307	::-webkit-scrollbar-track {
308	  background: transparent;
309	}
310	::-webkit-scrollbar-thumb {
311	  background-color: var(--color-border);
312	  border-radius: 3px;
313	}
