@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

@theme {
  /* ─── Accent ─────────────────────────────────────────────── */
  --color-accent-brand: oklch(62% 0.21 264);        /* #5e6ad2 — electric indigo */
  --color-accent-brand-subtle: oklch(62% 0.21 264 / 0.12);
  --color-accent-brand-emphasis: oklch(55% 0.22 264); /* hover/pressed */
  --color-accent-brand-foreground: oklch(100% 0 0);

  /* ─── Background layers — Light ──────────────────────────── */
  --color-canvas: oklch(99% 0 0);           /* page background */
  --color-surface: oklch(100% 0 0);         /* card / panel */
  --color-surface-raised: oklch(97% 0.005 220); /* elevated card */
  --color-overlay: oklch(100% 0 0);         /* dialog / popover */

  /* ─── Foreground — Light ──────────────────────────────────── */
  --color-fg-primary: oklch(11% 0.013 220);   /* headings, body */
  --color-fg-secondary: oklch(38% 0.009 220); /* labels, captions */
  --color-fg-tertiary: oklch(55% 0.007 220);  /* placeholders, hints */
  --color-fg-disabled: oklch(72% 0.005 220);

  /* ─── Border — Light ──────────────────────────────────────── */
  --color-border-subtle: oklch(95% 0.006 220);
  --color-border-default: oklch(91% 0.010 220);
  --color-border-strong: oklch(78% 0.010 220);

  /* ─── Semantic — shared across light/dark via relative values */

  /* Success */
  --color-success-subtle: oklch(97% 0.025 145);
  --color-success-default: oklch(56% 0.19 145);   /* #22c55e equiv */
  --color-success-emphasis: oklch(48% 0.19 145);
  --color-success-fg: oklch(30% 0.14 145);

  /* Warning */
  --color-warning-subtle: oklch(97% 0.030 75);
  --color-warning-default: oklch(65% 0.18 72);    /* #f59e0b equiv */
  --color-warning-emphasis: oklch(57% 0.19 72);
  --color-warning-fg: oklch(35% 0.14 72);

  /* Danger */
  --color-danger-subtle: oklch(97% 0.025 27);
  --color-danger-default: oklch(51% 0.22 27);     /* #ef4444 equiv */
  --color-danger-emphasis: oklch(44% 0.22 27);
  --color-danger-fg: oklch(30% 0.18 27);

  /* Info */
  --color-info-subtle: oklch(97% 0.018 230);
  --color-info-default: oklch(58% 0.18 230);
  --color-info-emphasis: oklch(50% 0.18 230);
  --color-info-fg: oklch(30% 0.14 230);

  /* ─── Scan state colors ───────────────────────────────────── */
  --color-scan-pending: oklch(55% 0.007 220);     /* neutral grey */
  --color-scan-running: oklch(62% 0.21 264);      /* accent indigo */
  --color-scan-completed: oklch(56% 0.19 145);    /* success green */
  --color-scan-failed: oklch(51% 0.22 27);        /* danger red */

  /* ─── shadcn token aliases (light defaults) ──────────────── */
  --color-background: var(--color-canvas);
  --color-foreground: var(--color-fg-primary);
  --color-card: var(--color-surface);
  --color-card-foreground: var(--color-fg-primary);
  --color-popover: var(--color-overlay);
  --color-popover-foreground: var(--color-fg-primary);
  --color-primary: var(--color-accent-brand);
  --color-primary-foreground: var(--color-accent-brand-foreground);
  --color-secondary: oklch(95% 0.006 220);
  --color-secondary-foreground: var(--color-fg-primary);
  --color-muted: oklch(96% 0.006 220);
  --color-muted-foreground: var(--color-fg-secondary);
  --color-accent: oklch(95% 0.006 220);
  --color-accent-foreground: var(--color-fg-primary);
  --color-destructive: var(--color-danger-default);
  --color-destructive-foreground: oklch(100% 0 0);
  --color-border: var(--color-border-default);
  --color-input: var(--color-border-default);
  --color-ring: var(--color-accent-brand);

  /* ─── Sidebar tokens ─────────────────────────────────────── */
  --sidebar: oklch(11% 0.025 222);
  --sidebar-background: oklch(11% 0.025 222);
  --sidebar-foreground: oklch(52% 0.010 220);
  --sidebar-foreground-active: oklch(95% 0.005 220);
  --sidebar-primary: var(--color-accent-brand);
  --sidebar-primary-foreground: oklch(100% 0 0);
  --sidebar-accent: oklch(17% 0.020 222);          /* hover bg */
  --sidebar-accent-foreground: oklch(80% 0.008 220);
  --sidebar-border: oklch(17% 0.018 222);
  --sidebar-ring: var(--color-accent-brand);
  --sidebar-item-active-bg: oklch(92% 0.004 250);  /* light — subtle elevated active */
  --sidebar-item-hover-bg: oklch(95% 0.003 250);   /* light — even subtler hover */
  --sidebar-width: 15rem;                          /* 240px — Linear-style */
  --sidebar-width-mobile: 17rem;
  --sidebar-width-icon: 3.5rem;                    /* 56px collapsed */

  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);

  /* ─── Radius ─────────────────────────────────────────────── */
  --radius: 0.5rem;                      /* 8px — Vercel-tight */
  --radius-sm: calc(var(--radius) - 4px); /* 4px */
  --radius-md: calc(var(--radius) - 2px); /* 6px */
  --radius-lg: var(--radius);             /* 8px */
  --radius-xl: calc(var(--radius) + 4px); /* 12px */
  --radius-full: 9999px;

  /* ─── Shadows — single unified system ───────────────────── */
  --shadow-none: none;
  --shadow-xs: 0 0 0 1px oklch(0% 0 0 / 0.04), 0 1px 2px oklch(0% 0 0 / 0.03);
  --shadow-sm: 0 0 0 1px oklch(0% 0 0 / 0.05), 0 2px 4px oklch(0% 0 0 / 0.04);
  --shadow-md: 0 0 0 1px oklch(0% 0 0 / 0.06), 0 4px 12px oklch(0% 0 0 / 0.06);
  --shadow-lg: 0 0 0 1px oklch(0% 0 0 / 0.08), 0 8px 24px oklch(0% 0 0 / 0.10);
  --shadow-xl: 0 0 0 1px oklch(0% 0 0 / 0.10), 0 16px 48px oklch(0% 0 0 / 0.14);

  /* ─── Typography ─────────────────────────────────────────── */
  --font-sans: var(--font-inter), system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-mono: var(--font-geist-mono), ui-monospace, "Cascadia Code", "Fira Code", monospace;

  /* ─── Motion ─────────────────────────────────────────────── */
  --duration-instant: 50ms;
  --duration-fast: 150ms;
  --duration-base: 200ms;
  --duration-slow: 300ms;
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.87, 0, 0.13, 1);

  /* ─── Keyframes ──────────────────────────────────────────── */
  --animate-accordion-down: accordion-down 0.2s ease-out;
  --animate-accordion-up: accordion-up 0.2s ease-out;
  --animate-fade-in: fade-in var(--duration-base) var(--ease-out);
  --animate-scale-in: scale-in var(--duration-fast) var(--ease-out);
  --animate-slide-up: slide-up var(--duration-base) var(--ease-out);
  --animate-slide-in-right: slide-in-right var(--duration-base) var(--ease-out);
  --animate-pulse-ring: pulse-ring 1.5s ease-in-out infinite;

  /* ─── Misc ───────────────────────────────────────────────── */
  --topbar-height: 56px;
}

/* ── Dark mode overrides ──────────────────────────────────────── */

.dark {
  /* Background layers */
  --color-canvas: oklch(9% 0.013 220);
  --color-surface: oklch(12% 0.013 220);
  --color-surface-raised: oklch(15% 0.013 220);
  --color-overlay: oklch(13% 0.015 220);

  /* Foreground */
  --color-fg-primary: oklch(93% 0.008 220);
  --color-fg-secondary: oklch(62% 0.009 220);
  --color-fg-tertiary: oklch(44% 0.007 220);
  --color-fg-disabled: oklch(32% 0.005 220);

  /* Border */
  --color-border-subtle: oklch(18% 0.010 220);
  --color-border-default: oklch(22% 0.013 220);
  --color-border-strong: oklch(32% 0.013 220);

  /* Semantic — dark mode subtle backgrounds flip to dark-tinted */
  --color-success-subtle: oklch(18% 0.040 145);
  --color-success-fg: oklch(72% 0.18 145);
  --color-warning-subtle: oklch(18% 0.040 72);
  --color-warning-fg: oklch(78% 0.17 72);
  --color-danger-subtle: oklch(18% 0.040 27);
  --color-danger-fg: oklch(72% 0.20 27);
  --color-info-subtle: oklch(16% 0.030 230);
  --color-info-fg: oklch(72% 0.17 230);

  /* shadcn token aliases — dark */
  --color-background: var(--color-canvas);
  --color-foreground: var(--color-fg-primary);
  --color-card: var(--color-surface);
  --color-card-foreground: var(--color-fg-primary);
  --color-popover: var(--color-overlay);
  --color-popover-foreground: var(--color-fg-primary);
  --color-primary: oklch(65% 0.20 264);
  --color-primary-foreground: oklch(100% 0 0);
  --color-secondary: oklch(18% 0.013 220);
  --color-secondary-foreground: var(--color-fg-primary);
  --color-muted: oklch(16% 0.013 220);
  --color-muted-foreground: var(--color-fg-secondary);
  --color-accent: oklch(18% 0.013 220);
  --color-accent-foreground: var(--color-fg-primary);
  --color-destructive: oklch(55% 0.22 27);
  --color-destructive-foreground: oklch(100% 0 0);
  --color-border: var(--color-border-default);
  --color-input: var(--color-border-default);
  --color-ring: oklch(65% 0.20 264);

  /* Sidebar active/hover — dark mode */
  --sidebar-item-active-bg: oklch(22% 0.008 250);  /* dark — slightly lighter than sidebar bg */
  --sidebar-item-hover-bg: oklch(18% 0.006 250);   /* dark — in between */

  /* Shadows — dark mode: border-dominant, minimal blur */
  --shadow-xs: 0 0 0 1px oklch(100% 0 0 / 0.06);
  --shadow-sm: 0 0 0 1px oklch(100% 0 0 / 0.07), 0 2px 4px oklch(0% 0 0 / 0.3);
  --shadow-md: 0 0 0 1px oklch(100% 0 0 / 0.08), 0 4px 12px oklch(0% 0 0 / 0.4);
  --shadow-lg: 0 0 0 1px oklch(100% 0 0 / 0.09), 0 8px 24px oklch(0% 0 0 / 0.5);
  --shadow-xl: 0 0 0 1px oklch(100% 0 0 / 0.10), 0 16px 48px oklch(0% 0 0 / 0.6);
}

@keyframes accordion-down {
  from { height: 0; }
  to { height: var(--radix-accordion-content-height); }
}

@keyframes accordion-up {
  from { height: var(--radix-accordion-content-height); }
  to { height: 0; }
}

@keyframes fade-in {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes scale-in {
  from { opacity: 0; transform: scale(0.97); }
  to { opacity: 1; transform: scale(1); }
}

@keyframes slide-up {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes slide-in-right {
  from { opacity: 0; transform: translateX(12px); }
  to { opacity: 1; transform: translateX(0); }
}

@keyframes pulse-ring {
  0% { box-shadow: 0 0 0 0 color-mix(in oklch, var(--color-accent-brand) 35%, transparent); }
  70% { box-shadow: 0 0 0 8px transparent; }
  100% { box-shadow: 0 0 0 0 transparent; }
}

/* ── Base styles ─────────────────────────────────────────────── */

* {
  border-color: var(--color-border);
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  background-color: var(--color-background);
  color: var(--color-foreground);
  font-family: var(--font-sans);
  font-feature-settings: 'cv11', 'ss01';
}

*:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--color-background), 0 0 0 4px color-mix(in oklch, var(--color-primary) 25%, transparent);
}

/* ── Utilities ───────────────────────────────────────────────── */

.text-balance {
  text-wrap: balance;
}

.text-2xs {
  font-size: 0.6875rem;
  line-height: 1rem;
}

.scrollbar-thin {
  scrollbar-width: thin;
  scrollbar-color: var(--color-border) transparent;
}

/* ── Reduced motion ──────────────────────────────────────────── */

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* ── Custom scrollbar (WebKit) ───────────────────────────────── */

::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background-color: var(--color-border);
  border-radius: 3px;
}

'use client'

import Link from 'next/link'
import { usePathname } from 'next/navigation'
import {
  LayoutDashboard,
  ScanLine,
  FileText,
  Puzzle,
  Settings,
  Zap,
  TrendingUp,
  Swords,
  Code2,
  Gift,
  Activity,
  Search,
} from 'lucide-react'
import { Progress } from '@/components/ui/progress'
import {
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupLabel,
  SidebarGroupContent,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarFooter,
  SidebarHeader,
  useSidebar,
} from '@/components/ui/sidebar'
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/components/ui/tooltip'
import { useAuth } from '@/contexts/AuthContext'
import { useFeatureFlag } from '@/hooks/use-feature-flag'
import { useTeams } from '@/hooks/use-teams'
import { TeamSwitcher } from '@/components/team/TeamSwitcher'
import { isProPlus } from '@/types/index'
import { cn } from '@/lib/utils'

interface NavItem {
  title: string
  url: string
  icon: React.ElementType
  flagKey?: string
  proOnly?: boolean
}

interface NavGroup {
  label: string
  items: NavItem[]
}

const NAV_GROUPS: NavGroup[] = [
  {
    label: 'Workspace',
    items: [
      { title: 'Dashboard', url: '/dashboard', icon: LayoutDashboard },
      { title: 'New Scan', url: '/scan', icon: ScanLine },
    ],
  },
  {
    label: 'Analyze',
    items: [
      { title: 'My Reports', url: '/reports', icon: FileText },
      { title: 'Score History', url: '/history', icon: TrendingUp },
      { title: 'Competitors', url: '/competitors', icon: Swords },
    ],
  },
  {
    label: 'Manage',
    items: [
      { title: 'Integrations', url: '/integrations', icon: Puzzle, flagKey: 'integrations_enabled' },
      { title: 'Monitoring', url: '/monitoring', icon: Activity, proOnly: true },
    ],
  },
  {
    label: 'Account',
    items: [
      { title: 'Refer & Earn', url: '/referrals', icon: Gift },
      { title: 'API', url: '/api-settings', icon: Code2, proOnly: true },
      { title: 'Settings', url: '/settings', icon: Settings },
    ],
  },
]

function openCommandPalette() {
  window.dispatchEvent(
    new KeyboardEvent('keydown', { key: 'k', metaKey: true, bubbles: true })
  )
}

export function AppSidebar() {
  const { state } = useSidebar()
  const collapsed = state === 'collapsed'
  const pathname = usePathname()
  const { profile } = useAuth()
  const { data: teams } = useTeams()
  const showTeamSwitcher =
    !collapsed && profile && isProPlus(profile.plan) && (teams?.length ?? 0) >= 0

  const integrationsEnabled = useFeatureFlag('integrations_enabled', true)

  const isActive = (path: string) =>
    pathname === path || pathname.startsWith(path + '/')

  const filterItems = (items: NavItem[]) =>
    items.filter((item) => {
      if (item.flagKey === 'integrations_enabled') return integrationsEnabled
      if (item.proOnly && profile) return isProPlus(profile.plan)
      return true
    })

  const scansUsed = profile?.scans_used ?? 0
  const scanLimit = profile?.scan_limit ?? 3
  const usagePercent = scanLimit > 0 ? Math.round((scansUsed / scanLimit) * 100) : 0
  const planLabel = profile?.plan ?? 'free'
  const isUnlimited = planLabel === 'agency' || planLabel === 'pro'
  const showUpgrade = !isUnlimited

  return (
    <Sidebar collapsible="icon" className="border-r-0" aria-label="Main navigation">
      <SidebarHeader className="px-4 py-5 group-data-[collapsible=icon]:px-2 group-data-[collapsible=icon]:py-4 group-data-[collapsible=icon]:items-center">
        <Link
          href="/dashboard"
          className="flex items-center gap-2.5 group-data-[collapsible=icon]:justify-center group-data-[collapsible=icon]:w-full"
        >
          <div className="flex h-7 w-7 items-center justify-center rounded-lg bg-sidebar-primary shrink-0">
            <ScanLine className="h-3.5 w-3.5 text-white" />
          </div>
          {!collapsed && (
            <span className="text-base font-semibold tracking-tight text-[--sidebar-foreground-active]">
              ConvertScan
            </span>
          )}
        </Link>
        {showTeamSwitcher && (
          <div className="mt-3 -mx-1">
            <TeamSwitcher />
          </div>
        )}
      </SidebarHeader>

      <SidebarContent className="px-2 group-data-[collapsible=icon]:px-1">
        {NAV_GROUPS.map((group, gi) => {
          const visibleItems = filterItems(group.items)
          if (visibleItems.length === 0) return null

          return (
            <SidebarGroup key={gi}>
              {!collapsed && (
                <SidebarGroupLabel className="text-[10px] font-medium uppercase tracking-wider text-sidebar-foreground/50 px-3 py-1.5 mt-2">
                  {group.label}
                </SidebarGroupLabel>
              )}
              <SidebarGroupContent>
                <SidebarMenu className="space-y-0.5">
                  {visibleItems.map((item) => {
                    const active = isActive(item.url)
                    return (
                      <SidebarMenuItem key={item.title}>
                        <SidebarMenuButton
                          asChild
                          tooltip={item.title}
                          isActive={active}
                          className={cn(
                            'h-9 transition-colors duration-150 rounded-md',
                            active
                              ? 'bg-[--sidebar-item-active-bg] text-[--sidebar-foreground-active]'
                              : 'text-sidebar-foreground hover:bg-[--sidebar-item-hover-bg] hover:text-[--sidebar-foreground-active]'
                          )}
                        >
                          <Link href={item.url}>
                            <item.icon
                              className={cn(
                                'h-4 w-4 shrink-0',
                                active
                                  ? 'text-[--sidebar-foreground-active]'
                                  : 'text-sidebar-foreground/60'
                              )}
                            />
                            <span className="text-sm font-medium">{item.title}</span>
                          </Link>
                        </SidebarMenuButton>
                      </SidebarMenuItem>
                    )
                  })}
                </SidebarMenu>
              </SidebarGroupContent>
            </SidebarGroup>
          )
        })}
      </SidebarContent>

      <SidebarFooter className="p-3 group-data-[collapsible=icon]:p-2 group-data-[collapsible=icon]:items-center">
        {/* Footer card — expanded */}
        {!collapsed && (
          <>
            <div className="rounded-lg border border-sidebar-border p-3 mb-0">
              <div className="flex items-center justify-between mb-2">
                <span className="text-xs font-medium text-sidebar-foreground capitalize">
                  {planLabel} plan
                </span>
                {!isUnlimited && (
                  <span className="text-xs font-medium text-sidebar-foreground tabular-nums">
                    {scansUsed}/{scanLimit} scans
                  </span>
                )}
              </div>
              {!isUnlimited && (
                <Progress value={usagePercent} className="h-1 mb-3" />
              )}
              {showUpgrade && (
                <Link
                  href="/pricing"
                  className="flex items-center justify-center gap-2 w-full rounded-md bg-sidebar-primary px-3 py-2 text-sm font-semibold text-white transition-opacity hover:opacity-90"
                >
                  <Zap className="h-4 w-4" />
                  Upgrade Plan
                </Link>
              )}
            </div>

            {/* ⌘K hint row */}
            <button
              type="button"
              onClick={openCommandPalette}
              className="mt-2 flex items-center w-full rounded-md bg-sidebar-accent/50 px-3 h-8 transition-colors hover:bg-sidebar-accent"
            >
              <Search className="h-3.5 w-3.5 text-sidebar-foreground/50 shrink-0 mr-2" />
              <span className="flex-1 text-left text-xs text-sidebar-foreground/70">
                Search...
              </span>
              <kbd className="text-[10px] text-sidebar-foreground/50 font-mono">
                ⌘K
              </kbd>
            </button>
          </>
        )}

        {/* Collapsed footer — icon pill with tooltip */}
        {collapsed && (
          <TooltipProvider>
            <Tooltip>
              <TooltipTrigger asChild>
                {showUpgrade ? (
                  <Link
                    href="/pricing"
                    aria-label="Upgrade Plan"
                    className="flex h-10 w-10 items-center justify-center rounded-md bg-sidebar-primary text-white transition-opacity hover:opacity-90"
                  >
                    <Zap className="h-4 w-4" />
                  </Link>
                ) : (
                  <div
                    aria-label={`${planLabel} plan`}
                    className="flex h-10 w-10 items-center justify-center rounded-md bg-sidebar-accent text-sidebar-foreground/70 cursor-default"
                  >
                    <Zap className="h-4 w-4" />
                  </div>
                )}
              </TooltipTrigger>
              <TooltipContent side="right" className="text-xs">
                {isUnlimited
                  ? `${planLabel} plan — unlimited`
                  : `${planLabel} · ${scansUsed}/${scanLimit} scans`}
              </TooltipContent>
            </Tooltip>
          </TooltipProvider>
        )}
      </SidebarFooter>
    </Sidebar>
  )
}

