761	function SupportTab() {
762	  const [subject, setSubject] = useState("");
763	  const [message, setMessage] = useState("");
764	  const [priority, setPriority] = useState<SupportPriority>("normal");
765	  const [subjectError, setSubjectError] = useState<string | null>(null);
766	  const [messageError, setMessageError] = useState<string | null>(null);
767	
768	  const submitRequest = useSubmitSupportRequest();
769	  const myRequests = useMySupportRequests();
770	
771	  const handleSubmit = () => {
772	    let valid = true;
773	    if (!subject.trim()) {
774	      setSubjectError("Subject is required.");
775	      valid = false;
776	    } else if (subject.length > 100) {
777	      setSubjectError("Subject must be 100 characters or less.");
778	      valid = false;
779	    } else {
780	      setSubjectError(null);
781	    }
782	
783	    if (!message.trim()) {
784	      setMessageError("Message is required.");
785	      valid = false;
786	    } else if (message.length < 20) {
787	      setMessageError("Message must be at least 20 characters.");
788	      valid = false;
789	    } else if (message.length > 2000) {
790	      setMessageError("Message must be 2000 characters or less.");
791	      valid = false;
792	    } else {
793	      setMessageError(null);
794	    }
795	
796	    if (!valid) return;
797	
798	    submitRequest.mutate(
799	      { subject: subject.trim(), message: message.trim(), priority },
800	      {
801	        onSuccess: () => {
802	          setSubject("");
803	          setMessage("");
804	          setPriority("normal");
