'use client';

import { useState, useEffect, useRef } from "react";
import { useRouter } from "next/navigation";
import {
  User,
  Camera,
  CreditCard,
  Bell,
  Key,
  AlertTriangle,
  Trash2,
  Download,
  ExternalLink,
  Loader2,
  TrendingUp,
  Eye,
  EyeOff,
  Check,
  X,
  Zap,
  LifeBuoy,
  Send,
} from "lucide-react";
import { createClient } from "@/lib/supabase/client";
import { MIN_PASSWORD_LENGTH } from "@/lib/constants";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Progress } from "@/components/ui/progress";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { Skeleton } from "@/components/ui/skeleton";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from "@/components/ui/tabs";
import { PageHeader } from "@/components/shared/PageHeader";
import { ErrorState } from "@/components/shared/ErrorState";
import { PremiumLock } from "@/components/shared/PremiumLock";
import { PageTransition } from "@/components/shared/PageTransition";
import { MonitoringSettingsCard } from "@/components/shared/MonitoringSettingsCard";
import { useAuth } from "@/contexts/AuthContext";
import { useUpdateProfile, useUpdateEmailPreferences } from "@/hooks/use-profile";
import { useCustomerPortal, useUsage } from "@/hooks/use-billing";
import { useSubmitSupportRequest, useMySupportRequests } from "@/hooks/use-support";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import type { SupportPriority } from "@/hooks/admin/use-admin-support";
import type { EmailPreferences } from "@/types";

export default function SettingsPage() {
  const router = useRouter();
  const { profile, loading: authLoading } = useAuth();
  const updateProfile = useUpdateProfile();
  const updateEmailPrefs = useUpdateEmailPreferences();
  const portal = useCustomerPortal();
  const usage = useUsage();

  // Form state
  const [fullName, setFullName] = useState("");
  const [companyName, setCompanyName] = useState("");
  const [websiteUrl, setWebsiteUrl] = useState("");
  const [showPasswordChange, setShowPasswordChange] = useState(false);

  // Password change fields
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [showNewPassword, setShowNewPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [passwordUpdating, setPasswordUpdating] = useState(false);

  // Populate form once profile loads
  const seeded = useRef(false);
  useEffect(() => {
    if (profile && !seeded.current) {
      setFullName(profile.full_name ?? "");
      setCompanyName(profile.company_name ?? "");
      setWebsiteUrl(profile.website_url ?? "");
      seeded.current = true;
    }
  }, [profile]);

  // Email preferences
  const DEFAULT_EMAIL_PREFS: EmailPreferences = { marketing: false, digest: true, scan_alerts: true };
  const [emailPrefs, setEmailPrefs] = useState<EmailPreferences>(DEFAULT_EMAIL_PREFS);
  const emailPrefsSeeded = useRef(false);

  useEffect(() => {
    if (profile && !emailPrefsSeeded.current) {
      const prefs = profile.email_preferences;
      if (prefs) {
        setEmailPrefs({
          marketing: prefs.marketing ?? false,
          digest: prefs.digest ?? true,
          scan_alerts: prefs.scan_alerts ?? true,
        });
      }
      emailPrefsSeeded.current = true;
    }
  }, [profile]);

  const handleEmailPrefChange = (key: keyof EmailPreferences, value: boolean) => {
    const next: EmailPreferences = { ...emailPrefs, [key]: value };
    setEmailPrefs(next);
    updateEmailPrefs.mutate(next, {
      onSuccess: () => toast.success("Preferences saved"),
      onError: () => toast.error("Failed to save preferences"),
    });
  };

  const handlePasswordChange = async () => {
    if (!newPassword) {
      toast.error("New password is required.");
      return;
    }
    if (newPassword.length < MIN_PASSWORD_LENGTH) {
      toast.error("Password must be at least 8 characters.");
      return;
    }
    if (newPassword !== confirmPassword) {
      toast.error("Passwords do not match.");
      return;
    }

    setPasswordUpdating(true);
    const supabase = createClient();
    const { error } = await supabase.auth.updateUser({ password: newPassword });
    setPasswordUpdating(false);

    if (error) {
      toast.error(error.message ?? "Failed to update password. Please try again.");
      return;
    }

    toast.success("Password updated successfully.");
    setNewPassword("");
    setConfirmPassword("");
    setShowPasswordChange(false);
  };

  const handleSave = () => {
    updateProfile.mutate(
      {
        full_name: fullName.trim() || undefined,
        company_name: companyName.trim() || null,
        website_url: websiteUrl.trim() || null,
      },
      {
        onSuccess: () => toast.success("Profile saved"),
        onError: () => toast.error("Failed to save profile"),
      }
    );
  };

  if (authLoading || !profile) {
    return (
      <PageTransition>
        <div className="space-y-6">
          <div className="space-y-2">
            <Skeleton className="h-7 w-32" />
            <Skeleton className="h-4 w-64" />
          </div>
          <Skeleton className="h-12 w-80" />
          <Skeleton className="h-96" />
        </div>
      </PageTransition>
    );
  }

  const initials = profile.full_name?.split(" ").map((n) => n[0]).join("") ?? "?";
  const cycleEnd = profile.billing_cycle_end
    ? new Date(profile.billing_cycle_end).toLocaleDateString("en-US", {
        month: "long",
        day: "numeric",
        year: "numeric",
      })
    : "N/A";

  return (
    <PageTransition>
      <div className="space-y-6">
        <PageHeader title="Settings" description="Manage your account, billing, and preferences" />

        <Tabs defaultValue="profile" className="space-y-6">
          <TabsList className="bg-transparent p-0 h-auto gap-0 flex-wrap border-b border-border/50 rounded-none w-full justify-start">
            {[
              { value: "profile", icon: User, label: "Profile" },
              { value: "billing", icon: CreditCard, label: "Billing" },
              { value: "notifications", icon: Bell, label: "Notifications" },
              { value: "api", icon: Key, label: "API Keys" },
              { value: "support", icon: LifeBuoy, label: "Support" },
            ].map((tab) => (
              <TabsTrigger
                key={tab.value}
                value={tab.value}
                className="rounded-none border-b-2 border-transparent px-4 py-2.5 text-sm data-[state=active]:border-primary data-[state=active]:bg-transparent data-[state=active]:shadow-none data-[state=active]:text-foreground"
              >
                <tab.icon className="mr-2 h-4 w-4" /> {tab.label}
              </TabsTrigger>
            ))}
          </TabsList>

          {/* ── Profile ────────────────────────────────────────── */}
          <TabsContent value="profile" className="space-y-6">
            <Card className="border-border/50 shadow-xs">
              <CardHeader>
                <CardTitle className="text-base">Profile information</CardTitle>
                <CardDescription>This is how you appear in shared reports and team settings</CardDescription>
              </CardHeader>
              <CardContent className="space-y-6">
                <div className="flex items-center gap-4">
                  <div className="group relative cursor-pointer">
                    <Avatar className="h-16 w-16">
                      <AvatarFallback className="bg-primary/8 text-primary text-xl font-bold">
                        {initials}
                      </AvatarFallback>
                    </Avatar>
                    <div className="absolute inset-0 flex items-center justify-center rounded-full bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity">
                      <Camera className="h-5 w-5 text-white" />
                    </div>
                  </div>
                  <div>
                    <p className="text-sm font-medium text-foreground">{profile.full_name}</p>
                    <p className="text-xs text-muted-foreground">{profile.email}</p>
                    <Badge variant="outline" className="mt-1 text-2xs capitalize">{profile.plan} plan</Badge>
                  </div>
                </div>
                <Separator />
                <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                  <div className="space-y-2">
                    <Label htmlFor="s-name">Full name</Label>
                    <Input
                      id="s-name"
                      value={fullName}
                      onChange={(e) => setFullName(e.target.value)}
                      className="border-border/50"
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="s-email">Email</Label>
                    <Input
                      id="s-email"
                      defaultValue={profile.email}
                      disabled
                      className="border-border/50 bg-muted/40"
                    />
                    <p className="text-xs text-muted-foreground">Contact support to change your email</p>
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="s-company">Company</Label>
                    <Input
                      id="s-company"
                      value={companyName}
                      onChange={(e) => setCompanyName(e.target.value)}
                      placeholder="Your company"
                      className="border-border/50"
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="s-website">Website</Label>
                    <Input
                      id="s-website"
                      value={websiteUrl}
                      onChange={(e) => setWebsiteUrl(e.target.value)}
                      placeholder="https://your-website.com"
                      className="border-border/50"
                    />
                  </div>
                </div>
                <div className="space-y-2">
                  <Label>Password</Label>
                  {showPasswordChange ? (
                    <div className="space-y-3 rounded-lg border border-border/50 p-4">
                      <div className="space-y-2">
                        <Label htmlFor="s-new-pw" className="text-xs">New password</Label>
                        <div className="relative">
                          <Input
                            id="s-new-pw"
                            type={showNewPassword ? "text" : "password"}
                            placeholder="Enter new password (min. 8 characters)"
                            value={newPassword}
                            onChange={(e) => setNewPassword(e.target.value)}
                            className="border-border/50 pr-10"
                            disabled={passwordUpdating}
                          />
                          <button
                            type="button"
                            className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
                            onClick={() => setShowNewPassword((v) => !v)}
                            aria-label={showNewPassword ? "Hide password" : "Show password"}
                            tabIndex={-1}
                          >
                            {showNewPassword ? (
                              <EyeOff className="h-4 w-4" />
                            ) : (
                              <Eye className="h-4 w-4" />
                            )}
                          </button>
                        </div>
                      </div>
                      <div className="space-y-2">
                        <Label htmlFor="s-confirm-pw" className="text-xs">Confirm new password</Label>
                        <div className="relative">
                          <Input
                            id="s-confirm-pw"
                            type={showConfirmPassword ? "text" : "password"}
                            placeholder="Confirm new password"
                            value={confirmPassword}
                            onChange={(e) => setConfirmPassword(e.target.value)}
                            className="border-border/50 pr-10"
                            disabled={passwordUpdating}
                          />
                          <button
                            type="button"
                            className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
                            onClick={() => setShowConfirmPassword((v) => !v)}
                            aria-label={showConfirmPassword ? "Hide password" : "Show password"}
                            tabIndex={-1}
                          >
                            {showConfirmPassword ? (
                              <EyeOff className="h-4 w-4" />
                            ) : (
                              <Eye className="h-4 w-4" />
                            )}
                          </button>
                        </div>
                      </div>
                      <div className="flex gap-2">
                        <Button
                          size="sm"
                          disabled={passwordUpdating}
                          onClick={() => void handlePasswordChange()}
                        >
                          {passwordUpdating ? (
                            <><Loader2 className="mr-2 h-3.5 w-3.5 animate-spin" />Updating&hellip;</>
                          ) : (
                            "Update password"
                          )}
                        </Button>
                        <Button
                          size="sm"
                          variant="ghost"
                          disabled={passwordUpdating}
                          onClick={() => {
                            setShowPasswordChange(false);
                            setNewPassword("");
                            setConfirmPassword("");
                          }}
                        >
                          Cancel
                        </Button>
                      </div>
                    </div>
                  ) : (
                    <div className="flex gap-2">
                      <Input
                        type="password"
                        defaultValue="placeholder"
                        disabled
                        className="flex-1 border-border/50 bg-muted/40"
                        aria-label="Current password placeholder"
                      />
                      <Button
                        variant="outline"
                        className="border-border/50 shrink-0"
                        onClick={() => setShowPasswordChange(true)}
                      >
                        Change password
                      </Button>
                    </div>
                  )}
                </div>
                <Button onClick={handleSave} disabled={updateProfile.isPending}>
                  {updateProfile.isPending ? (
                    <><Loader2 className="mr-2 h-4 w-4 animate-spin" />Saving...</>
                  ) : (
                    "Save changes"
                  )}
                </Button>
              </CardContent>
            </Card>

            {/* Danger zone */}
            <Card className="border-red-200/60 shadow-none">
              <CardHeader>
                <CardTitle className="text-base text-[--color-danger-fg] flex items-center gap-2">
                  <AlertTriangle className="h-4 w-4" />
                  Danger zone
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm font-medium text-foreground">Export all data</p>
                    <p className="text-xs text-muted-foreground">Download all your scans and reports as a ZIP file</p>
                  </div>
                  <Button
                    variant="outline"
                    size="sm"
                    className="border-border/50"
                    onClick={() => toast.info("Data export is coming soon. We'll notify you when it's available.")}
                  >
                    <Download className="mr-1.5 h-3.5 w-3.5" />
                    Export
                  </Button>
                </div>
                <Separator />
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm font-medium text-[--color-danger-fg]">Delete account</p>
                    <p className="text-xs text-muted-foreground">Permanently delete your account and all associated data. This action cannot be undone.</p>
                  </div>
                  <Button
                    variant="outline"
                    size="sm"
                    className="border-red-200 text-[--color-danger-fg] hover:bg-[--color-danger-subtle]/50 hover:text-[--color-danger-fg]"
                    onClick={() => toast.error("Account deletion requires contacting support@convertscan.com", { duration: 6000 })}
                  >
                    <Trash2 className="mr-1.5 h-3.5 w-3.5" />
                    Delete
                  </Button>
                </div>
              </CardContent>
            </Card>
          </TabsContent>

          {/* ── Billing ────────────────────────────────────────── */}
          <TabsContent value="billing" className="space-y-6">
            <Card className="overflow-hidden border border-border shadow-xs">
              <CardContent className="p-6 space-y-5">
                <div className="flex items-start justify-between gap-4">
                  <div>
                    <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-1">
                      Current Plan
                    </p>
                    <div className="flex items-center gap-2">
                      <h3 className="text-2xl font-bold text-foreground capitalize">
                        {profile.plan}
                      </h3>
                      <Badge
                        className={cn(
                          "text-xs font-semibold px-2.5 py-0.5 uppercase",
                          profile.plan === "agency"
                            ? "bg-violet-100 text-violet-700 border-violet-200"
                            : profile.plan === "pro"
                            ? "bg-indigo-100 text-indigo-700 border-indigo-200"
                            : "bg-muted text-muted-foreground border-border"
                        )}
                        variant="outline"
                      >
                        {profile.plan === "pro" && <Zap className="mr-1 h-2.5 w-2.5" />}
                        {profile.plan.toUpperCase()}
                      </Badge>
                    </div>
                    {profile.plan !== "free" && (
                      <p className="mt-1 text-xs text-muted-foreground">
                        {usage.billingCycleEnd
                          ? `Renews on ${cycleEnd}`
                          : "Active subscription"}
                      </p>
                    )}
                  </div>
                  {profile.plan !== "free" && (
                    <Button
                      variant="outline"
                      size="sm"
                      className="shrink-0 border-border/50"
                      disabled={portal.isPending}
                      onClick={() => portal.mutate()}
                    >
                      {portal.isPending ? (
                        <><Loader2 className="mr-2 h-3.5 w-3.5 animate-spin" />Opening...</>
                      ) : (
                        <>
                          <ExternalLink className="mr-1.5 h-3.5 w-3.5" />
                          Manage Billing
                        </>
                      )}
                    </Button>
                  )}
                </div>

                {/* Usage bar */}
                <div className="space-y-2">
                  <div className="flex items-center justify-between">
                    <span className="text-sm text-muted-foreground">Scans used this month</span>
                    <span className="text-sm font-semibold tabular-nums text-foreground">
                      {usage.scansUsed} / {usage.scanLimit}
                    </span>
                  </div>
                  <Progress
                    value={usage.usagePercent}
                    className={cn(
                      "h-2",
                      usage.usagePercent >= 100 && "[&>div]:bg-[--color-danger-subtle]0",
                      usage.usagePercent >= 70 && usage.usagePercent < 100 && "[&>div]:bg-[--color-warning-subtle]0"
                    )}
                  />
                  <p className="text-xs text-muted-foreground">
                    {usage.billingCycleEnd
                      ? `Resets on ${cycleEnd}`
                      : "Resets at the start of each calendar month"}
                  </p>
                </div>

                {profile.plan === "free" && (
                  <Button
                    className="w-full rounded-lg font-semibold"
                    onClick={() => router.push("/pricing")}
                  >
                    <TrendingUp className="mr-2 h-4 w-4" />
                    Upgrade to Pro &mdash; $49/month
                  </Button>
                )}
              </CardContent>
            </Card>

            {/* Plan comparison — only for free users */}
            {profile.plan === "free" && (
              <Card className="border-border/50 shadow-xs">
