                          <th className="pb-3 text-center text-xs font-semibold text-muted-foreground w-24">Free</th>
                          <th className="pb-3 text-center text-xs font-semibold text-indigo-600 w-24">Pro</th>
                          <th className="pb-3 text-center text-xs font-medium text-muted-foreground w-24">Agency</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-border/30">
                        {[
                          { label: "Scans / month", free: "3", pro: "25", agency: "500" },
                          { label: "AI suggestions", free: false, pro: true, agency: true },
                          { label: "AI copy rewrites", free: false, pro: true, agency: true },
                          { label: "PDF report export", free: false, pro: true, agency: true },
                          { label: "Score monitoring", free: false, pro: true, agency: true },
                          { label: "Integrations", free: false, pro: false, agency: true },
                          { label: "White-label reports", free: false, pro: false, agency: true },
                          { label: "API access", free: false, pro: false, agency: true },
                        ].map((row) => (
                          <tr key={row.label}>
                            <td className="py-2.5 text-xs text-foreground/80">{row.label}</td>
                            {[row.free, row.pro, row.agency].map((val, i) => (
                              <td key={i} className="py-2.5 text-center">
                                {val === true ? (
                                  <Check className="mx-auto h-4 w-4 text-green-500" />
                                ) : val === false ? (
                                  <X className="mx-auto h-4 w-4 text-muted-foreground/30" />
                                ) : (
                                  <span className={cn("text-xs", i === 1 && "font-semibold text-indigo-600")}>
                                    {val}
                                  </span>
                                )}
                              </td>
                            ))}
                          </tr>
                        ))}
