            <Card className="border-border/50 shadow-xs">
              <CardHeader>
                <div className="flex items-center justify-between">
                  <CardTitle className="text-base">Billing history</CardTitle>
                  {profile.plan !== "free" && (
                    <Button
                      variant="ghost"
                      size="sm"
                      className="text-xs text-muted-foreground"
                      disabled={portal.isPending}
                      onClick={() => portal.mutate()}
                    >
                      {portal.isPending ? (
                        <Loader2 className="h-3.5 w-3.5 animate-spin" />
                      ) : (
                        <>
                          <ExternalLink className="mr-1.5 h-3.5 w-3.5" />
                          View all invoices
                        </>
                      )}
                    </Button>
                  )}
                </div>
              </CardHeader>
              <CardContent>
                {profile.plan === "free" ? (
                  <div className="rounded-lg border border-dashed border-border/50 p-8 text-center">
                    <CreditCard className="mx-auto mb-3 h-8 w-8 text-muted-foreground/40" />
                    <p className="text-sm font-medium text-foreground">No billing history yet</p>
                    <p className="mt-1 text-xs text-muted-foreground">
                      Invoices will appear here once you upgrade to a paid plan
                    </p>
                    <Button
                      size="sm"
                      variant="outline"
                      className="mt-4 border-border/50"
                      onClick={() => router.push("/pricing")}
                    >
                      View plans
                    </Button>
                  </div>
                ) : (
                  <div className="rounded-lg border border-dashed border-border/50 p-8 text-center">
                    <p className="text-sm text-muted-foreground">
                      View and download invoices in the billing portal
                    </p>
                    <Button
                      size="sm"
                      variant="outline"
                      className="mt-4 border-border/50"
                      disabled={portal.isPending}
                      onClick={() => portal.mutate()}
                    >
                      {portal.isPending ? (
                        <><Loader2 className="mr-2 h-4 w-4 animate-spin" />Opening...</>
                      ) : (
                        <>
                          <ExternalLink className="mr-1.5 h-3.5 w-3.5" />
                          Open billing portal
                        </>
                      )}
                    </Button>
                  </div>
                )}
              </CardContent>
            </Card>
          </TabsContent>

          {/* ── Notifications ──────────────────────────────────── */}
          <TabsContent value="notifications" className="space-y-6">
            <MonitoringSettingsCard
              isPro={profile?.plan === "pro" || profile?.plan === "agency"}
              userEmail={profile?.email}
            />
            <Card className="border-border/50 shadow-xs">
              <CardHeader>
                <CardTitle className="text-base">Email preferences</CardTitle>
                <CardDescription>Choose which emails you want to receive. Changes are saved automatically.</CardDescription>
              </CardHeader>
              <CardContent className="space-y-6">
                {([
                  {
                    key: "scan_alerts" as const,
                    label: "Scan alerts",
                    desc: "Email when a monitored page's score changes significantly",
                  },
                  {
                    key: "digest" as const,
                    label: "Weekly CRO digest",
                    desc: "Monday summary of your page scores and improvement opportunities",
                  },
                  {
                    key: "marketing" as const,
                    label: "Marketing &amp; tips",
                    desc: "CRO tips, case studies, product updates, and industry data",
                  },
                ] satisfies Array<{ key: keyof EmailPreferences; label: string; desc: string }>).map((item) => (
                  <div key={item.key} className="flex items-center justify-between">
                    <div>
                      <p className="text-sm font-medium text-foreground">{item.label}</p>
                      <p className="text-xs text-muted-foreground">{item.desc}</p>
                    </div>
                    <Switch
                      checked={emailPrefs[item.key]}
                      disabled={updateEmailPrefs.isPending}
                      onCheckedChange={(checked) => handleEmailPrefChange(item.key, checked)}
                    />
                  </div>
                ))}
              </CardContent>
            </Card>
          </TabsContent>

          {/* ── API Keys ───────────────────────────────────────── */}
          <TabsContent value="api">
            <PremiumLock message="REST API access is available on the Agency plan ($199/mo)">
              <Card className="border-border/50 shadow-xs">
                <CardHeader>
                  <CardTitle className="text-base">API keys</CardTitle>
                  <CardDescription>Use the REST API to run scans programmatically and integrate with your workflow</CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div className="flex items-center gap-3 rounded-lg bg-muted/40 p-4 font-mono">
                    <code className="flex-1 text-sm text-foreground select-all">sk_live_cRoBoT_&bull;&bull;&bull;&bull;&bull;&bull;&bull;&bull;&bull;&bull;&bull;&bull;&bull;&bull;&bull;&bull;&bull;&bull;&bull;&bull;</code>
                    <Button variant="outline" size="sm" onClick={() => toast.info("Upgrade to Agency plan to reveal your API key.")}>Reveal</Button>
                    <Button variant="outline" size="sm" onClick={() => { void navigator.clipboard.writeText("sk_live_cRoBoT_demo_key"); toast.success("API key copied to clipboard."); }}>Copy</Button>
                  </div>
                  <div className="flex gap-2">
                    <Button onClick={() => toast.info("API key generation is coming soon.")}>Generate new key</Button>
                    <Button variant="outline" className="border-border/50" onClick={() => window.open("https://docs.crobot.app/api", "_blank")}>
                      <ExternalLink className="mr-1.5 h-3.5 w-3.5" />
                      View API docs
                    </Button>
                  </div>
                  <p className="text-xs text-muted-foreground">
                    Rate limit: 100,000 API calls/month &middot; Keys are scoped to your account &middot; Rotate keys every 90 days
                  </p>
                </CardContent>
              </Card>
            </PremiumLock>
          </TabsContent>

          {/* ── Support ────────────────────────────────────────── */}
          <TabsContent value="support" className="space-y-6">
            <SupportTab />
          </TabsContent>
        </Tabs>
      </div>
    </PageTransition>
  );
}

// ── Support tab sub-component ─────────────────────────────────

const STATUS_BADGE_CLASSES: Record<string, string> = {
  open: "bg-[--color-warning-subtle] text-[--color-warning-fg]",
  in_progress: "bg-[--color-info-subtle] text-[--color-info-fg]",
  resolved: "bg-[--color-success-subtle] text-[--color-success-fg]",
  closed: "bg-muted text-muted-foreground",
};

function SupportTab() {
  const [subject, setSubject] = useState("");
  const [message, setMessage] = useState("");
  const [priority, setPriority] = useState<SupportPriority>("normal");
  const [subjectError, setSubjectError] = useState<string | null>(null);
  const [messageError, setMessageError] = useState<string | null>(null);

  const submitRequest = useSubmitSupportRequest();
  const myRequests = useMySupportRequests();

  const handleSubmit = () => {
    let valid = true;
    if (!subject.trim()) {
      setSubjectError("Subject is required.");
      valid = false;
    } else if (subject.length > 100) {
      setSubjectError("Subject must be 100 characters or less.");
      valid = false;
    } else {
      setSubjectError(null);
    }

    if (!message.trim()) {
      setMessageError("Message is required.");
      valid = false;
    } else if (message.length < 20) {
      setMessageError("Message must be at least 20 characters.");
      valid = false;
    } else if (message.length > 2000) {
      setMessageError("Message must be 2000 characters or less.");
      valid = false;
    } else {
      setMessageError(null);
    }

    if (!valid) return;

    submitRequest.mutate(
      { subject: subject.trim(), message: message.trim(), priority },
      {
        onSuccess: () => {
          setSubject("");
          setMessage("");
          setPriority("normal");
        },
      }
    );
  };

  return (
    <div className="space-y-6">
      <Card className="border-border/50 shadow-xs">
        <CardHeader>
          <CardTitle className="text-base">Contact Support</CardTitle>
          <CardDescription>
            Submit a support request and our team will get back to you.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-1.5">
            <Label htmlFor="support-subject">Subject</Label>
            <Input
              id="support-subject"
              value={subject}
              onChange={(e) => { setSubject(e.target.value); setSubjectError(null); }}
              placeholder="Brief description of your issue..."
              maxLength={100}
              className={cn("border-border/50", subjectError && "border-red-500")}
            />
            {subjectError && (
              <p className="text-xs text-[--color-danger-fg]">{subjectError}</p>
            )}
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="support-priority">Priority</Label>
            <Select value={priority} onValueChange={(v) => setPriority(v as SupportPriority)}>
              <SelectTrigger id="support-priority" className="border-border/50">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="normal">Normal</SelectItem>
                <SelectItem value="high">High</SelectItem>
                <SelectItem value="urgent">Urgent</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="support-message">
              Message
              <span className="ml-2 text-xs font-normal text-muted-foreground">
                ({message.length}/2000)
              </span>
            </Label>
            <Textarea
              id="support-message"
              value={message}
              onChange={(e) => { setMessage(e.target.value); setMessageError(null); }}
              placeholder="Describe your issue in detail..."
              maxLength={2000}
              className={cn("min-h-[120px] resize-none border-border/50", messageError && "border-red-500")}
            />
            {messageError && (
              <p className="text-xs text-[--color-danger-fg]">{messageError}</p>
            )}
          </div>

          <Button
            onClick={handleSubmit}
            disabled={submitRequest.isPending}
            className="w-full sm:w-auto"
          >
            {submitRequest.isPending ? (
              <Loader2 className="mr-2 h-3.5 w-3.5 animate-spin" />
            ) : (
              <Send className="mr-2 h-3.5 w-3.5" />
            )}
            {submitRequest.isPending ? "Submitting\u2026" : "Submit Request"}
          </Button>
        </CardContent>
      </Card>

      <Card className="border-border/50 shadow-xs">
        <CardHeader>
          <CardTitle className="text-base">My Support Requests</CardTitle>
          <CardDescription>
            Track the status of your submitted requests.
          </CardDescription>
        </CardHeader>
        <CardContent>
          {myRequests.isLoading ? (
            <div className="space-y-2">
              {Array.from({ length: 3 }).map((_, i) => (
                <Skeleton key={i} className="h-10 w-full rounded-lg" />
              ))}
            </div>
          ) : myRequests.isError ? (
            <ErrorState
              title="Failed to load requests"
              description="There was a problem fetching your support history. Try again."
              onRetry={() => void myRequests.refetch()}
            />
          ) : !myRequests.data || myRequests.data.length === 0 ? (
            <div className="rounded-xl border border-dashed border-border/50 py-8 text-center">
              <LifeBuoy className="mx-auto h-8 w-8 text-muted-foreground/40 mb-2" />
              <p className="text-sm text-muted-foreground">No support requests yet.</p>
            </div>
          ) : (
            <div className="rounded-xl border border-border/50 overflow-hidden">
              <Table>
                <TableHeader>
                  <TableRow className="bg-muted/40 hover:bg-muted/40">
                    <TableHead>Subject</TableHead>
                    <TableHead>Priority</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead>Submitted</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {myRequests.data.map((req) => (
                    <TableRow key={req.id}>
                      <TableCell className="text-sm font-medium max-w-[200px]">
                        <span className="truncate block">{req.subject}</span>
                      </TableCell>
                      <TableCell>
                        <Badge className="text-2xs px-1.5 py-0 capitalize bg-muted/50 text-foreground/70 border-0">
                          {req.priority}
                        </Badge>
                      </TableCell>
                      <TableCell>
                        <Badge className={`text-2xs px-1.5 py-0 border-0 ${STATUS_BADGE_CLASSES[req.status] ?? "bg-muted/50 text-foreground/70"}`}>
                          {req.status.replace("_", " ")}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-xs text-muted-foreground whitespace-nowrap">
                        {new Date(req.created_at).toLocaleDateString("en-US", {
                          month: "short",
                          day: "numeric",
                          year: "numeric",
                        })}
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

